	public static void main(String[] args){
		Scanner sc = new Scanner(System.in);
        int a = sc.nextInt();
        int b = sc.nextInt();
        int[] numbers = new int[b];
        for(int x = 0; x < b; x++){
            int number = sc.nextInt();
            numbers[x] = number;
        }

        boolean[] hasTooth = new boolean[a + 1];
        for(int i = 1; i <= a; i++) {
            hasTooth[i] = true; // Initially, all holes have teeth
        }

        for(int i = 0; i < b; i++) {
            int hole = numbers[i];
            hasTooth[hole] = !hasTooth[hole]; // Toggle the state of the tooth in the hole
        }

        int count = 0;
        for(int i = 1; i <= a; i++) {
            if(hasTooth[i]) {
                count++;
            }
        }

        System.out.println(count);
    }

